  1→package jlsm.sql;
  2→
  3→import java.util.ArrayList;
  4→import java.util.List;
  5→import java.util.Map;
  6→import java.util.Objects;
  7→
  8→/**
  9→ * Tokenizes a SQL string into a list of {@link Token}s.
 10→ *
 11→ * <p>
 12→ * Contract:
 13→ * <ul>
 14→ * <li>Receives: a non-null SQL string</li>
 15→ * <li>Returns: an immutable list of tokens, always ending with {@link TokenType#EOF}</li>
 16→ * <li>Side effects: none (stateless — new instance per tokenization)</li>
 17→ * <li>Error conditions: throws {@link SqlParseException} on unrecognised characters or unterminated
 18→ * string literals, with position information</li>
 19→ * </ul>
 20→ *
 21→ * <p>
 22→ * Handles: SQL keywords (case-insensitive), single-quoted string literals, numeric literals
 23→ * (integers and decimals), identifiers, comparison operators ({@code =}, {@code !=}, {@code <>},
 24→ * {@code <}, {@code <=}, {@code >}, {@code >=}), punctuation, and positional bind parameters
 25→ * ({@code ?}).
 26→ */
 27→public final class SqlLexer {
 28→
 29→    private static final Map<String, TokenType> KEYWORDS = Map.ofEntries(
 30→            Map.entry("SELECT", TokenType.SELECT), Map.entry("FROM", TokenType.FROM),
 31→            Map.entry("WHERE", TokenType.WHERE), Map.entry("AND", TokenType.AND),
 32→            Map.entry("OR", TokenType.OR), Map.entry("NOT", TokenType.NOT),
 33→            Map.entry("ORDER", TokenType.ORDER), Map.entry("BY", TokenType.BY),
 34→            Map.entry("ASC", TokenType.ASC), Map.entry("DESC", TokenType.DESC),
 35→            Map.entry("LIMIT", TokenType.LIMIT), Map.entry("OFFSET", TokenType.OFFSET),
 36→            Map.entry("BETWEEN", TokenType.BETWEEN), Map.entry("IS", TokenType.IS),
 37→            Map.entry("NULL", TokenType.NULL), Map.entry("TRUE", TokenType.TRUE),
 38→            Map.entry("FALSE", TokenType.FALSE), Map.entry("AS", TokenType.AS),
 39→            Map.entry("LIKE", TokenType.LIKE), Map.entry("IN", TokenType.IN),
 40→            Map.entry("MATCH", TokenType.MATCH),
 41→            Map.entry("VECTOR_DISTANCE", TokenType.VECTOR_DISTANCE));
 42→
 43→    /**
 44→     * Tokenizes the given SQL string.
 45→     *
 46→     * @param sql the SQL string to tokenize, must not be null
 47→     * @return an immutable list of tokens ending with EOF
 48→     * @throws SqlParseException if the input contains unrecognised characters or unterminated
 49→     *             string literals
 50→     */
 51→    public List<Token> tokenize(String sql) throws SqlParseException {
 52→        Objects.requireNonNull(sql, "sql");
 53→
 54→        final var tokens = new ArrayList<Token>();
 55→        final int len = sql.length();
 56→        int pos = 0;
 57→
 58→        while (pos < len) {
 59→            final char ch = sql.charAt(pos);
 60→
 61→            // Skip whitespace
 62→            if (Character.isWhitespace(ch)) {
 63→                pos++;
 64→                continue;
 65→            }
 66→
 67→            // Single-quoted string literal
 68→            if (ch == '\'') {
 69→                pos = readStringLiteral(sql, pos, tokens);
 70→                continue;
 71→            }
 72→
 73→            // Numeric literal (digit or decimal point followed by digit)
 74→            if (Character.isDigit(ch)
 75→                    || (ch == '.' && pos + 1 < len && Character.isDigit(sql.charAt(pos + 1)))) {
 76→                pos = readNumericLiteral(sql, pos, tokens);
 77→                continue;
 78→            }
 79→
 80→            // Identifier or keyword (starts with letter or underscore)
 81→            if (Character.isLetter(ch) || ch == '_') {
 82→                pos = readIdentifierOrKeyword(sql, pos, tokens);
 83→                continue;
 84→            }
 85→
 86→            // Operators and punctuation
 87→            switch (ch) {
 88→                case '(' -> {
 89→                    tokens.add(new Token(TokenType.LPAREN, "(", pos));
 90→                    pos++;
 91→                }
 92→                case ')' -> {
 93→                    tokens.add(new Token(TokenType.RPAREN, ")", pos));
 94→                    pos++;
 95→                }
 96→                case ',' -> {
 97→                    tokens.add(new Token(TokenType.COMMA, ",", pos));
 98→                    pos++;
 99→                }
100→                case '.' -> {
101→                    tokens.add(new Token(TokenType.DOT, ".", pos));
102→                    pos++;
103→                }
104→                case '*' -> {
105→                    tokens.add(new Token(TokenType.STAR, "*", pos));
106→                    pos++;
107→                }
108→                case '?' -> {
109→                    tokens.add(new Token(TokenType.PARAMETER, "?", pos));
110→                    pos++;
111→                }
112→                case '=' -> {
113→                    tokens.add(new Token(TokenType.EQ, "=", pos));
114→                    pos++;
115→                }
116→                case '!' -> {
117→                    if (pos + 1 < len && sql.charAt(pos + 1) == '=') {
118→                        tokens.add(new Token(TokenType.NE, "!=", pos));
119→                        pos += 2;
120→                    } else {
121→                        throw new SqlParseException("Unexpected character '!' at position " + pos
122→                                + " — did you mean '!='?", pos);
123→                    }
124→                }
125→                case '<' -> {
126→                    if (pos + 1 < len && sql.charAt(pos + 1) == '=') {
127→                        tokens.add(new Token(TokenType.LTE, "<=", pos));
128→                        pos += 2;
129→                    } else if (pos + 1 < len && sql.charAt(pos + 1) == '>') {
130→                        tokens.add(new Token(TokenType.NE, "<>", pos));
131→                        pos += 2;
132→                    } else {
133→                        tokens.add(new Token(TokenType.LT, "<", pos));
134→                        pos++;
135→                    }
136→                }
137→                case '>' -> {
138→                    if (pos + 1 < len && sql.charAt(pos + 1) == '=') {
139→                        tokens.add(new Token(TokenType.GTE, ">=", pos));
140→                        pos += 2;
141→                    } else {
142→                        tokens.add(new Token(TokenType.GT, ">", pos));
143→                        pos++;
144→                    }
145→                }
146→                default -> throw new SqlParseException(
147→                        "Unrecognised character '" + ch + "' at position " + pos, pos);
148→            }
149→        }
150→
151→        tokens.add(new Token(TokenType.EOF, "", len));
152→        return List.copyOf(tokens);
153→    }
154→
155→    private int readStringLiteral(String sql, int start, List<Token> tokens)
156→            throws SqlParseException {
157→        assert sql.charAt(start) == '\'' : "expected opening quote";
158→
159→        final var sb = new StringBuilder();
160→        int pos = start + 1;
161→        final int len = sql.length();
162→
163→        while (pos < len) {
164→            final char ch = sql.charAt(pos);
165→            if (ch == '\'') {
166→                // Check for escaped quote ''
167→                if (pos + 1 < len && sql.charAt(pos + 1) == '\'') {
168→                    sb.append('\'');
169→                    pos += 2;
170→                } else {
171→                    // End of string literal
172→                    tokens.add(new Token(TokenType.STRING_LITERAL, sb.toString(), start));
173→                    return pos + 1;
174→                }
175→            } else {
176→                sb.append(ch);
177→                pos++;
178→            }
179→        }
180→
181→        throw new SqlParseException("Unterminated string literal starting at position " + start,
182→                start);
183→    }
184→
185→    private int readNumericLiteral(String sql, int start, List<Token> tokens) {
186→        int pos = start;
187→        final int len = sql.length();
188→        boolean seenDot = false;
189→
190→        while (pos < len) {
191→            final char ch = sql.charAt(pos);
192→            if (Character.isDigit(ch)) {
193→                pos++;
194→            } else if (ch == '.' && !seenDot) {
195→                seenDot = true;
196→                pos++;
197→            } else {
198→                break;
199→            }
200→        }
201→
202→        tokens.add(new Token(TokenType.NUMBER_LITERAL, sql.substring(start, pos), start));
203→        return pos;
204→    }
205→
206→    private int readIdentifierOrKeyword(String sql, int start, List<Token> tokens) {
207→        int pos = start;
208→        final int len = sql.length();
209→
210→        while (pos < len) {
211→            final char ch = sql.charAt(pos);
212→            if (Character.isLetterOrDigit(ch) || ch == '_') {
213→                pos++;
214→            } else {
215→                break;
216→            }
217→        }
218→
219→        final String text = sql.substring(start, pos);
220→        final String upper = text.toUpperCase();
221→        final TokenType keyword = KEYWORDS.get(upper);
222→
223→        if (keyword != null) {
224→            tokens.add(new Token(keyword, text, start));
225→        } else {
226→            tokens.add(new Token(TokenType.IDENTIFIER, text, start));
227→        }
228→
229→        return pos;
230→    }
231→}
