  1→package jlsm.table;
  2→
  3→import jlsm.core.io.MemorySerializer;
  4→import jdk.incubator.vector.ByteVector;
  5→import jdk.incubator.vector.DoubleVector;
  6→import jdk.incubator.vector.FloatVector;
  7→import jdk.incubator.vector.IntVector;
  8→import jdk.incubator.vector.LongVector;
  9→import jdk.incubator.vector.VectorShuffle;
 10→import jdk.incubator.vector.VectorSpecies;
 11→
 12→import java.lang.foreign.MemorySegment;
 13→import java.lang.foreign.ValueLayout;
 14→import java.nio.charset.StandardCharsets;
 15→import java.util.List;
 16→import java.util.Objects;
 17→
 18→/**
 19→ * Binary serializer for {@link JlsmDocument} values.
 20→ *
 21→ * <p>
 22→ * The binary format consists of a header (schema version, field count, null bitmask, optional
 23→ * boolean bitmask) followed by serialized non-null, non-boolean field values in schema order.
 24→ *
 25→ * <p>
 26→ * Schema versioning: the header stores the write-time field count. On deserialization with a newer
 27→ * schema, only the write-time fields are decoded; additional fields in the current schema are left
 28→ * {@code null}.
 29→ *
 30→ * <p>
 31→ * Contiguous numeric arrays (INT32, INT64, FLOAT32, FLOAT64) use SIMD byte-swap acceleration via
 32→ * {@code jdk.incubator.vector}.
 33→ */
 34→public final class DocumentSerializer {
 35→
 36→    private DocumentSerializer() {
 37→    }
 38→
 39→    /**
 40→     * Returns a {@link MemorySerializer} for {@link JlsmDocument} values conforming to the given
 41→     * schema.
 42→     *
 43→     * @param schema the schema describing the document structure; must not be null
 44→     * @return a MemorySerializer for JlsmDocument
 45→     */
 46→    public static MemorySerializer<JlsmDocument> forSchema(JlsmSchema schema) {
 47→        Objects.requireNonNull(schema, "schema must not be null");
 48→        return new SchemaSerializer(schema);
 49→    }
 50→
 51→    // =========================================================================
 52→    // Implementation
 53→    // =========================================================================
 54→
 55→    /** SIMD species for byte-level operations (used for byte-swap shuffles). */
 56→    private static final VectorSpecies<Byte> BYTE_SPECIES = ByteVector.SPECIES_PREFERRED;
 57→
 58→    /** Byte-swap shuffle for INT32 / FLOAT32 (4-byte elements). */
 59→    private static final VectorShuffle<Byte> BSWAP32;
 60→
 61→    /** Byte-swap shuffle for INT64 / FLOAT64 (8-byte elements). */
 62→    private static final VectorShuffle<Byte> BSWAP64;
 63→
 64→    static {
 65→        final int byteLen = BYTE_SPECIES.length();
 66→        final int[] idx32 = new int[byteLen];
 67→        final int[] idx64 = new int[byteLen];
 68→        for (int i = 0; i + 3 < byteLen; i += 4) {
 69→            idx32[i + 0] = i + 3;
 70→            idx32[i + 1] = i + 2;
 71→            idx32[i + 2] = i + 1;
 72→            idx32[i + 3] = i + 0;
 73→        }
 74→        for (int i = 0; i + 7 < byteLen; i += 8) {
 75→            idx64[i + 0] = i + 7;
 76→            idx64[i + 1] = i + 6;
 77→            idx64[i + 2] = i + 5;
 78→            idx64[i + 3] = i + 4;
 79→            idx64[i + 4] = i + 3;
 80→            idx64[i + 5] = i + 2;
 81→            idx64[i + 6] = i + 1;
 82→            idx64[i + 7] = i + 0;
 83→        }
 84→        BSWAP32 = VectorShuffle.fromArray(BYTE_SPECIES, idx32, 0);
 85→        BSWAP64 = VectorShuffle.fromArray(BYTE_SPECIES, idx64, 0);
 86→    }
 87→
 88→    // -------------------------------------------------------------------------
 89→    // Serializer implementation
 90→    // -------------------------------------------------------------------------
 91→
 92→    private static final class SchemaSerializer implements MemorySerializer<JlsmDocument> {
 93→
 94→        private final JlsmSchema schema;
 95→
 96→        SchemaSerializer(JlsmSchema schema) {
 97→            this.schema = schema;
 98→        }
 99→
100→        @Override
101→        public MemorySegment serialize(JlsmDocument doc) {
102→            Objects.requireNonNull(doc, "doc must not be null");
103→            assert doc.schema() == schema || doc.schema().name().equals(schema.name())
104→                    : "document schema mismatch";
105→
106→            final List<FieldDefinition> fields = schema.fields();
107→            final int fieldCount = fields.size();
108→            final Object[] values = doc.values();
109→
110→            // Count boolean fields
111→            final int boolCount = countBoolFields(fields);
112→
113→            // Header size: 2 (version) + 2 (fieldCount) + ceil(fieldCount/8) (null mask)
114→            // + (boolCount > 0 ? ceil(boolCount/8) : 0) (bool mask)
115→            final int nullMaskBytes = (fieldCount + 7) / 8;
116→            final int boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
117→            final int headerSize = 2 + 2 + nullMaskBytes + boolMaskBytes;
118→
119→            // Two-pass: measure then encode
120→            final int payloadSize = measureFields(fields, values);
121→            final int totalSize = headerSize + payloadSize;
122→
123→            final byte[] buf = new byte[totalSize];
124→
125→            // Write header
126→            writeShortBE(buf, 0, (short) schema.version());
127→            writeShortBE(buf, 2, (short) fieldCount);
128→            // Null bitmask
129→            buildNullMask(fields, values, buf, 4);
130→            // Boolean bitmask
131→            if (boolCount > 0) {
132→                buildBoolMask(fields, values, buf, 4 + nullMaskBytes);
133→            }
134→
135→            // Write values
136→            final Cursor cursor = new Cursor(buf, headerSize);
137→            encodeFields(fields, values, cursor);
138→
139→            assert cursor.pos == totalSize : "cursor.pos should equal totalSize";
140→            return MemorySegment.ofArray(buf);
141→        }
142→
143→        @Override
144→        public JlsmDocument deserialize(MemorySegment segment) {
145→            Objects.requireNonNull(segment, "segment must not be null");
146→
147→            final byte[] buf = segment.toArray(ValueLayout.JAVA_BYTE);
148→            final Cursor cursor = new Cursor(buf, 0);
149→
150→            // Read header
151→            final int _ = readShortBE(buf, cursor.advance(2)) & 0xFFFF;
152→            final int writeFieldCount = readShortBE(buf, cursor.advance(2)) & 0xFFFF;
153→
154→            final List<FieldDefinition> currentFields = schema.fields();
155→            final int currentFieldCount = currentFields.size();
156→
157→            // We only read min(writeFieldCount, currentFieldCount) fields
158→            final int readCount = Math.min(writeFieldCount, currentFieldCount);
159→
160→            // Count bool fields in the *write-time* schema (same field list up to writeFieldCount)
161→            // We use the current schema's first writeFieldCount fields for the null/bool masks.
162→            // For the boolMask we count booleans among the first writeFieldCount fields.
163→            final int writeBoolCount = countBoolFieldsUpTo(currentFields, writeFieldCount);
164→            final int writeNullMaskBytes = (writeFieldCount + 7) / 8;
165→            final int writeBoolMaskBytes = writeBoolCount > 0 ? (writeBoolCount + 7) / 8 : 0;
166→
167→            final int nullMaskOffset = cursor.advance(writeNullMaskBytes);
168→            final int boolMaskOffset = writeBoolCount > 0 ? cursor.advance(writeBoolMaskBytes) : -1;
169→
170→            // Decode values
171→            final Object[] values = new Object[currentFieldCount];
172→            // Fields beyond readCount remain null (new fields added in a later schema version)
173→
174→            int boolIdx = 0; // index among BOOLEAN fields seen so far
175→            for (int i = 0; i < readCount; i++) {
176→                final FieldDefinition fd = currentFields.get(i);
177→                final boolean isNull = isNullBit(buf, nullMaskOffset, i);
178→                if (isNull) {
179→                    // Track bool index even when null
180→                    if (fd.type() == FieldType.Primitive.BOOLEAN) {
181→                        boolIdx++;
182→                    }
183→                    values[i] = null;
184→                    continue;
185→                }
186→                if (fd.type() == FieldType.Primitive.BOOLEAN) {
187→                    // Value is encoded in the bool bitmask
188→                    assert boolMaskOffset >= 0 : "bool bitmask offset should be set";
189→                    values[i] = isBoolBit(buf, boolMaskOffset, boolIdx);
190→                    boolIdx++;
191→                } else {
192→                    values[i] = decodeField(buf, cursor, fd.type());
193→                }
194→            }
195→
196→            // If writeFieldCount > currentFieldCount we need to skip the extra encoded fields.
197→            // However, since we can't know the sizes of unknown fields (their types may differ
198→            // from the current schema), we handle schema shrinkage gracefully by only reading
199→            // min(writeFieldCount, currentFieldCount). Extra write-time fields beyond the current
200→            // schema are simply ignored — the cursor position won't matter after this point.
201→
202→            return new JlsmDocument(schema, values);
203→        }
204→    }
205→
206→    // =========================================================================
207→    // Measure helpers (first pass)
208→    // =========================================================================
209→
210→    private static int measureFields(List<FieldDefinition> fields, Object[] values) {
211→        int total = 0;
212→        for (int i = 0; i < fields.size(); i++) {
213→            final FieldDefinition fd = fields.get(i);
214→            final Object val = values[i];
215→            if (val == null) {
216→                continue; // null → no value bytes
217→            }
218→            total += measureField(fd.type(), val);
219→        }
220→        return total;
221→    }
222→
223→    private static int measureField(FieldType type, Object value) {
224→        return switch (type) {
225→            case FieldType.Primitive p -> switch (p) {
226→                case STRING -> {
227→                    final byte[] utf8 = ((String) value).getBytes(StandardCharsets.UTF_8);
228→                    yield varIntSize(utf8.length) + utf8.length;
229→                }
230→                case INT8 -> 1;
231→                case INT16 -> 2;
232→                case INT32 -> 4;
233→                case INT64 -> 8;
234→                case FLOAT16 -> 2;
235→                case FLOAT32 -> 4;
236→                case FLOAT64 -> 8;
237→                case BOOLEAN -> 0; // packed in bitmask
238→                case TIMESTAMP -> 8;
239→            };
240→            case FieldType.ArrayType at -> {
241→                final Object[] arr = (Object[]) value;
242→                int sz = varIntSize(arr.length);
243→                for (Object elem : arr) {
244→                    sz += (elem == null) ? 0 : measureField(at.elementType(), elem);
245→                }
246→                yield sz;
247→            }
248→            case FieldType.ObjectType ot -> {
249→                final JlsmDocument sub = (JlsmDocument) value;
250→                final List<FieldDefinition> subFields = ot.fields();
251→                final int subBoolCount = countBoolFields(subFields);
252→                final int subNullBytes = (subFields.size() + 7) / 8;
253→                final int subBoolBytes = subBoolCount > 0 ? (subBoolCount + 7) / 8 : 0;
254→                int sz = subNullBytes + subBoolBytes;
255→                sz += measureFields(subFields, sub.values());
256→                yield sz;
257→            }
258→        };
259→    }
