261→    // =========================================================================
262→    // Encode helpers (second pass)
263→    // =========================================================================
264→
265→    private static void encodeFields(List<FieldDefinition> fields, Object[] values, Cursor c) {
266→        for (int i = 0; i < fields.size(); i++) {
267→            final Object val = values[i];
268→            if (val == null) {
269→                continue;
270→            }
271→            encodeField(c, fields.get(i).type(), val);
272→        }
273→    }
274→
275→    private static void encodeField(Cursor c, FieldType type, Object value) {
276→        switch (type) {
277→            case FieldType.Primitive p -> {
278→                switch (p) {
279→                    case STRING -> {
280→                        final byte[] utf8 = ((String) value).getBytes(StandardCharsets.UTF_8);
281→                        writeVarInt(c, utf8.length);
282→                        System.arraycopy(utf8, 0, c.buf, c.pos, utf8.length);
283→                        c.pos += utf8.length;
284→                    }
285→                    case INT8 -> c.buf[c.pos++] = (Byte) value;
286→                    case INT16 -> {
287→                        writeShortBE(c.buf, c.pos, (Short) value);
288→                        c.pos += 2;
289→                    }
290→                    case INT32 -> {
291→                        writeIntBE(c.buf, c.pos, (Integer) value);
292→                        c.pos += 4;
293→                    }
294→                    case INT64 -> {
295→                        writeLongBE(c.buf, c.pos, (Long) value);
296→                        c.pos += 8;
297→                    }
298→                    case FLOAT16 -> {
299→                        writeShortBE(c.buf, c.pos, (Short) value);
300→                        c.pos += 2;
301→                    }
302→                    case FLOAT32 -> {
303→                        writeIntBE(c.buf, c.pos, Float.floatToRawIntBits((Float) value));
304→                        c.pos += 4;
305→                    }
306→                    case FLOAT64 -> {
307→                        writeLongBE(c.buf, c.pos, Double.doubleToRawLongBits((Double) value));
308→                        c.pos += 8;
309→                    }
310→                    case BOOLEAN -> {
311→                        // Boolean values are packed in the bool bitmask; nothing here
312→                    }
313→                    case TIMESTAMP -> {
314→                        writeLongBE(c.buf, c.pos, (Long) value);
315→                        c.pos += 8;
316→                    }
317→                }
318→            }
319→            case FieldType.ArrayType at -> encodeArray(c, at.elementType(), (Object[]) value);
320→            case FieldType.ObjectType ot -> encodeObject(c, ot, (JlsmDocument) value);
321→        }
322→    }
323→
324→    private static void encodeArray(Cursor c, FieldType elemType, Object[] arr) {
325→        writeVarInt(c, arr.length);
326→        // SIMD-accelerated paths for contiguous numeric types
327→        if (elemType == FieldType.Primitive.INT32) {
328→            encodeInt32Array(c, arr);
329→        } else if (elemType == FieldType.Primitive.INT64) {
330→            encodeInt64Array(c, arr);
331→        } else if (elemType == FieldType.Primitive.FLOAT32) {
332→            encodeFloat32Array(c, arr);
333→        } else if (elemType == FieldType.Primitive.FLOAT64) {
334→            encodeFloat64Array(c, arr);
335→        } else {
336→            for (Object elem : arr) {
337→                if (elem != null) {
338→                    encodeField(c, elemType, elem);
339→                }
340→            }
341→        }
342→    }
343→
344→    private static void encodeObject(Cursor c, FieldType.ObjectType ot, JlsmDocument sub) {
345→        final List<FieldDefinition> subFields = ot.fields();
346→        final Object[] subValues = sub.values();
347→        final int boolCount = countBoolFields(subFields);
348→        final int nullMaskBytes = (subFields.size() + 7) / 8;
349→        final int boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
350→
351→        final int nullMaskStart = c.pos;
352→        c.pos += nullMaskBytes;
353→        final int boolMaskStart = boolCount > 0 ? c.pos : -1;
354→        if (boolCount > 0) {
355→            c.pos += boolMaskBytes;
356→        }
357→
358→        buildNullMask(subFields, subValues, c.buf, nullMaskStart);
359→        if (boolCount > 0) {
360→            buildBoolMask(subFields, subValues, c.buf, boolMaskStart);
361→        }
362→        encodeFields(subFields, subValues, c);
363→    }
