365→    // =========================================================================
366→    // SIMD encode paths
367→    // =========================================================================
368→
369→    private static void encodeInt32Array(Cursor c, Object[] arr) {
370→        final int simdLen = BYTE_SPECIES.length(); // bytes per SIMD register
371→        // Only use SIMD if we have enough data (at least one full vector worth of 4-byte ints)
372→        final int simdElems = simdLen / 4; // number of int32 elements per SIMD operation
373→        int i = 0;
374→        if (arr.length >= simdElems && simdLen >= 4) {
375→            final int[] ints = new int[simdElems];
376→            while (i + simdElems <= arr.length) {
377→                for (int j = 0; j < simdElems; j++) {
378→                    ints[j] = (Integer) arr[i + j];
379→                }
380→                // Load as bytes (little-endian native), swap to big-endian
381→                final ByteVector bv = IntVector.fromArray(IntVector.SPECIES_PREFERRED, ints, 0)
382→                        .reinterpretAsBytes();
383→                bv.rearrange(BSWAP32).intoArray(c.buf, c.pos);
384→                c.pos += simdLen;
385→                i += simdElems;
386→            }
387→        }
388→        // Scalar remainder
389→        while (i < arr.length) {
390→            writeIntBE(c.buf, c.pos, (Integer) arr[i++]);
391→            c.pos += 4;
392→        }
393→    }
394→
395→    private static void encodeInt64Array(Cursor c, Object[] arr) {
396→        final int simdLen = BYTE_SPECIES.length();
397→        final int simdElems = simdLen / 8;
398→        int i = 0;
399→        if (arr.length >= simdElems && simdLen >= 8) {
400→            final long[] longs = new long[simdElems];
401→            while (i + simdElems <= arr.length) {
402→                for (int j = 0; j < simdElems; j++) {
403→                    longs[j] = (Long) arr[i + j];
404→                }
405→                final ByteVector bv = LongVector.fromArray(LongVector.SPECIES_PREFERRED, longs, 0)
406→                        .reinterpretAsBytes();
407→                bv.rearrange(BSWAP64).intoArray(c.buf, c.pos);
408→                c.pos += simdLen;
409→                i += simdElems;
410→            }
411→        }
412→        while (i < arr.length) {
413→            writeLongBE(c.buf, c.pos, (Long) arr[i++]);
414→            c.pos += 8;
415→        }
416→    }
417→
418→    private static void encodeFloat32Array(Cursor c, Object[] arr) {
419→        final int simdLen = BYTE_SPECIES.length();
420→        final int simdElems = simdLen / 4;
421→        int i = 0;
422→        if (arr.length >= simdElems && simdLen >= 4) {
423→            final float[] floats = new float[simdElems];
424→            while (i + simdElems <= arr.length) {
425→                for (int j = 0; j < simdElems; j++) {
426→                    floats[j] = (Float) arr[i + j];
427→                }
428→                final ByteVector bv = FloatVector
429→                        .fromArray(FloatVector.SPECIES_PREFERRED, floats, 0).reinterpretAsBytes();
430→                bv.rearrange(BSWAP32).intoArray(c.buf, c.pos);
431→                c.pos += simdLen;
432→                i += simdElems;
433→            }
434→        }
435→        while (i < arr.length) {
436→            writeIntBE(c.buf, c.pos, Float.floatToRawIntBits((Float) arr[i++]));
437→            c.pos += 4;
438→        }
439→    }
440→
441→    private static void encodeFloat64Array(Cursor c, Object[] arr) {
442→        final int simdLen = BYTE_SPECIES.length();
443→        final int simdElems = simdLen / 8;
444→        int i = 0;
445→        if (arr.length >= simdElems && simdLen >= 8) {
446→            final double[] doubles = new double[simdElems];
447→            while (i + simdElems <= arr.length) {
448→                for (int j = 0; j < simdElems; j++) {
449→                    doubles[j] = (Double) arr[i + j];
450→                }
451→                final ByteVector bv = DoubleVector
452→                        .fromArray(DoubleVector.SPECIES_PREFERRED, doubles, 0).reinterpretAsBytes();
453→                bv.rearrange(BSWAP64).intoArray(c.buf, c.pos);
454→                c.pos += simdLen;
455→                i += simdElems;
456→            }
457→        }
458→        while (i < arr.length) {
459→            writeLongBE(c.buf, c.pos, Double.doubleToRawLongBits((Double) arr[i++]));
460→            c.pos += 8;
461→        }
462→    }
