609→        final long[] tmp = new long[simdElems];
610→        int i = 0;
611→        if (count >= simdElems && simdLen >= 8) {
612→            while (i + simdElems <= count) {
613→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP64)
614→                        .reinterpretAsLongs().intoArray(tmp, 0);
615→                for (int j = 0; j < simdElems; j++) {
616→                    result[i + j] = tmp[j];
617→                }
618→                cursor.pos += simdLen;
619→                i += simdElems;
620→            }
621→        }
622→        while (i < count) {
623→            result[i++] = readLongBE(buf, cursor.pos);
624→            cursor.pos += 8;
625→        }
626→        return result;
627→    }
