677→    // =========================================================================
678→    // Bitmask helpers
679→    // =========================================================================
680→
681→    private static void buildNullMask(List<FieldDefinition> fields, Object[] values, byte[] buf,
682→            int offset) {
683→        for (int i = 0; i < fields.size(); i++) {
684→            if (values[i] == null) {
685→                buf[offset + i / 8] |= (byte) (1 << (i % 8));
686→            }
687→        }
688→    }
689→
690→    private static void buildBoolMask(List<FieldDefinition> fields, Object[] values, byte[] buf,
691→            int offset) {
692→        int boolIdx = 0;
693→        for (int i = 0; i < fields.size(); i++) {
694→            if (fields.get(i).type() == FieldType.Primitive.BOOLEAN) {
695→                final Object val = values[i];
696→                if (val instanceof Boolean b && b) {
697→                    buf[offset + boolIdx / 8] |= (byte) (1 << (boolIdx % 8));
698→                }
699→                boolIdx++;
700→            }
701→        }
702→    }
703→
704→    private static boolean isNullBit(byte[] buf, int maskOffset, int fieldIndex) {
705→        return (buf[maskOffset + fieldIndex / 8] & (1 << (fieldIndex % 8))) != 0;
706→    }
707→
708→    private static boolean isBoolBit(byte[] buf, int maskOffset, int boolIndex) {
709→        return (buf[maskOffset + boolIndex / 8] & (1 << (boolIndex % 8))) != 0;
710→    }
711→
712→    private static int countBoolFields(List<FieldDefinition> fields) {
713→        int count = 0;
714→        for (final FieldDefinition fd : fields) {
715→            if (fd.type() == FieldType.Primitive.BOOLEAN) {
716→                count++;
717→            }
718→        }
719→        return count;
720→    }
721→
722→    private static int countBoolFieldsUpTo(List<FieldDefinition> fields, int limit) {
723→        int count = 0;
724→        final int bound = Math.min(limit, fields.size());
725→        for (int i = 0; i < bound; i++) {
726→            if (fields.get(i).type() == FieldType.Primitive.BOOLEAN) {
727→                count++;
728→            }
729→        }
730→        return count;
731→    }
