 74→    /**
 75→     * Builds the 4-byte big-endian prefix {@code [termLen | termBytes]}. This sorts before all
 76→     * composite keys for this term.
 77→     */
 78→    static byte[] buildPrefix(byte[] termBytes) {
 79→        assert termBytes != null : "termBytes must not be null";
 80→        byte[] prefix = new byte[4 + termBytes.length];
 81→        int len = termBytes.length;
 82→        prefix[0] = (byte) ((len >>> 24) & 0xFF);
 83→        prefix[1] = (byte) ((len >>> 16) & 0xFF);
 84→        prefix[2] = (byte) ((len >>> 8) & 0xFF);
 85→        prefix[3] = (byte) (len & 0xFF);
 86→        System.arraycopy(termBytes, 0, prefix, 4, termBytes.length);
 87→        return prefix;
 88→    }
 89→
 90→    /**
 91→     * Increments {@code prefix} as a big-endian unsigned integer. Returns {@code null} on overflow
 92→     * (all bytes are {@code 0xFF}), indicating an unbounded scan is needed.
 93→     */
 94→    static MemorySegment incrementPrefix(byte[] prefix) {
 95→        assert prefix != null : "prefix must not be null";
 96→        byte[] incremented = prefix.clone();
 97→        for (int i = incremented.length - 1; i >= 0; i--) {
 98→            if ((incremented[i] & 0xFF) < 0xFF) {
 99→                incremented[i]++;
100→                return MemorySegment.ofArray(incremented);
101→            }
102→            incremented[i] = 0;
103→        }
104→        return null; // overflow
105→    }
106→
107→    /**
108→     * Builds a composite key {@code [termLen_be4 | termBytes | docIdBytes]}.
109→     */
110→    static MemorySegment compositeKey(byte[] termBytes, byte[] docIdBytes) {
111→        assert termBytes != null : "termBytes must not be null";
112→        assert docIdBytes != null : "docIdBytes must not be null";
113→        byte[] prefix = buildPrefix(termBytes);
114→        byte[] key = new byte[prefix.length + docIdBytes.length];
115→        System.arraycopy(prefix, 0, key, 0, prefix.length);
116→        System.arraycopy(docIdBytes, 0, key, prefix.length, docIdBytes.length);
117→        return MemorySegment.ofArray(key);
118→    }
