122→     * byte-lexicographic order matches numeric order.
123→     */
124→    static byte[] encodeLongTerm(long term) {
125→        long unsigned = term ^ Long.MIN_VALUE;
126→        byte[] bytes = new byte[8];
127→        for (int i = 7; i >= 0; i--) {
128→            bytes[i] = (byte) (unsigned & 0xFF);
129→            unsigned >>>= 8;
130→        }
131→        return bytes;
132→    }
