186→
187→    /** Returns the dot product of two float vectors using SIMD + scalar tail. */
188→    static float dotProduct(float[] a, float[] b) {
189→        assert a != null && b != null : "vectors must not be null";
190→        assert a.length == b.length : "vectors must have the same length";
191→        int i = 0, ub = SPECIES.loopBound(a.length);
192→        var acc = FloatVector.zero(SPECIES);
193→        for (; i < ub; i += SPECIES.length()) {
194→            acc = FloatVector.fromArray(SPECIES, a, i).fma(FloatVector.fromArray(SPECIES, b, i),
195→                    acc);
196→        }
197→        float sum = acc.reduceLanes(VectorOperators.ADD);
198→        for (; i < a.length; i++)
199→            sum += a[i] * b[i];
200→        return sum;
201→    }
202→
203→    /** Returns the cosine similarity in [−1, 1]; 0 if either vector has zero norm. */
204→    static float cosine(float[] a, float[] b) {
205→        float dot = dotProduct(a, b);
206→        float denom = (float) Math.sqrt(dotProduct(a, a) * dotProduct(b, b));
207→        return denom == 0.0f ? 0.0f : dot / denom;
208→    }
209→
210→    /** Returns the negated Euclidean distance ≤ 0; closer = less negative = higher score. */
211→    static float euclidean(float[] a, float[] b) {
212→        assert a.length == b.length : "vectors must have the same length";
213→        int i = 0, ub = SPECIES.loopBound(a.length);
214→        var acc = FloatVector.zero(SPECIES);
215→        for (; i < ub; i += SPECIES.length()) {
216→            var diff = FloatVector.fromArray(SPECIES, a, i)
217→                    .sub(FloatVector.fromArray(SPECIES, b, i));
218→            acc = diff.fma(diff, acc);
219→        }
220→        float sum = acc.reduceLanes(VectorOperators.ADD);
221→        for (; i < a.length; i++) {
222→            float d = a[i] - b[i];
223→            sum += d * d;
224→        }
225→        return -(float) Math.sqrt(sum);
226→    }
227→
228→    /** Dispatches to the appropriate similarity function; higher = more similar for all. */
229→    static float score(float[] a, float[] b, SimilarityFunction fn) {
230→        return switch (fn) {
231→            case COSINE -> cosine(a, b);
232→            case DOT_PRODUCT -> dotProduct(a, b);
233→            case EUCLIDEAN -> euclidean(a, b);
234→        };
235→    }
